"use client";

import Image from "next/image";
import Link from "next/link";
import { useEffect, useState } from "react";

interface HeroLogoProps {
  isInHeader?: boolean;
}

export default function HeroLogo({ isInHeader = false }: HeroLogoProps) {
  const [scrollProgress, setScrollProgress] = useState(0);

  useEffect(() => {
    const handleScroll = () => {
      // Le logo commence à bouger après 50px et termine à 200px
      const startScroll = 50;
      const endScroll = 200;
      const currentScroll = window.scrollY;

      if (currentScroll <= startScroll) {
        setScrollProgress(0);
      } else if (currentScroll >= endScroll) {
        setScrollProgress(1);
      } else {
        setScrollProgress((currentScroll - startScroll) / (endScroll - startScroll));
      }
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    handleScroll(); // Initial check
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // Logo dans le header - visible uniquement quand scrollProgress > 0
  if (isInHeader) {
    return (
      <div
        className="absolute left-1/2 top-1/2 transition-opacity duration-200"
        style={{
          opacity: scrollProgress,
          transform: "translate(-50%, -50%)",
        }}
      >
        <Link href="/">
          <Image
            src="/logo/logoFullBlack.png"
            alt="Form Me Logo"
            width={120}
            height={48}
            className="h-8 w-auto hidden lg:block"
            priority
          />
          <Image
            src="/logo/logoBlack.png"
            alt="Form Me Logo"
            width={100}
            height={36}
            className="lg:hidden"
            priority
          />
        </Link>
      </div>
    );
  }

  // Logo dans le hero - visible et se déplace vers le haut progressivement
  return (
    <div
      className="transition-all duration-200"
      style={{
        opacity: 1 - scrollProgress,
        transform: `translateY(${-scrollProgress * 100}px) scale(${1 - scrollProgress * 0.3})`,
      }}
    >
      <Link href="/">
        <Image
          src="/logo/logoFullBlack.png"
          alt="Form Me Logo"
          width={180}
          height={72}
          className="h-14 md:h-16 w-auto"
          priority
        />
      </Link>
    </div>
  );
}
